-- Route B (E7) POST verification, READ ONLY (catalog + aggregate counts; never a guest column). Expect every ok = true (history 1..16).
-- data_counts / other_logins_in_booking_groups are REPORTED, not asserted: the hosted data and logins are not assumed.
BEGIN READ ONLY;
SELECT 'instance_test' AS check_name, (SELECT count(*) = 1 AND bool_and(environment = 'test') FROM booking.instance) AS ok, NULL::text AS detail
UNION ALL
SELECT 'history_exactly_1_to_16', (SELECT count(*) = 0 FROM booking_migrations.applied a FULL JOIN (VALUES (1, 'booking_core', 'f1550b3ab41cad09c0ee65295c07e483faef7d55554f18f04b1a148a0f2e045a', '948afbb80ab046c59bb5828bd858558a4ca4f2b608b15a8b53f34a27ab8aef7c'), (2, 'roles_grants', 'f2a35ad4f92043bdb09573451ea22b6da8444da207d798ef1d0fdd60621d80b7', '107c2010d5d385f4b25350ce9e848f8f362d8bc4ed6374bbb959f8afd1b752cf'), (3, 'safety_corrections', '51143492f332bc771696a0c1cca241bc1fd078535f1a6e91dabd3c1b05b539f7', '5f6ce4613908eb4bc4601c1a10a7b7c9f54c78654190c69bbbca620c8a1907fb'), (4, 'capture_recovery', '2ffb8af83913e3090b87fbf28a264ef96f15707bdbef647f5098b39f143be472', '9a41c4eeb99f01470df7fa9c352b123383139a9d6cf339d9a1f785da8a1ddcab'), (5, 'db_clock_checkout_create', 'd487975b8bc5f451b7ca22d0b91330cf4365b5d315a4f8dbb3f5ccac3f368637', 'fbf0814e5b39d44eadd9728cce3ba272dfa9f59d81de146818a43c5a53fcca5d'), (6, 'api_rate_limits', '2ab8bd93af1671b5017ab896cb6faf0a78ab0875a3fd2c723ccbefe2a90b0183', 'ae746d4556b9ff0699bfce998805096dc6aa4dcf212641d3153c58f546522658'), (7, 'capture_claim_fence', 'ef46bdc35d98e9a2b38a1effaf767afa07e4a77eac1cce233c6762ce02c3bd9e', '512b93ea7c0cf7dfce3900966ef8b0dd333dab523f6cb9f986b21b30533c1273'), (8, 'settled_evidence_immutable', '2ecedc65abc1c51c4967f480df211611d987378caf81ce283b160ff849b6f903', '301ab430f27710e2a15c5d2d2d39e5c06f2ffe446d43469bdf63f76cfa708cd4'), (9, 'void_cancel_claim_fence', '868adf98dacab345fbcfdf544c09d305f26956b850836a164a3601161011bc8d', 'cffb3d0997ccf37599b29f583d7d4ecb252804d66c292faa5815c67152b46fe5'), (10, 'recording_evidence_link', '55244bf157b527bfbb0119fcb21979996ebbad454c1a154ed926f1a64b67e727', '232575bca986ef123a6ac95d356ab8f42a671a17711282b30277d6a0046e09d3'), (11, 'recording_owner_cases', '2448821d93093c32c4cb4d5cb58aaf81a633ab5cd64b5c0025213e73fe573762', '79cb74d8b8345218f8e2fb840207213c59c9ee744826d5b9a2952c3ddf1d565a'), (12, 'recording_assessments', '1b782b2027ed4d71f3714a97ef3f1d71829f7e552ed8da91f30c54c841a93ec1', '947927e827f9e715f09401bf26b114ae85ebeed0b930f0f89fc919b50c55ca19'), (13, 'recording_preflight_release', 'd9d8b4c2c677c764a0e6e8e615feb783c37d7c3226ac5b99a2ab8d8a227db239', 'db63c94eadbb9ea2058e1e100153a9c85a18ea4d7844c06082e5f523a3b3feb2'), (14, 'recording_completion_binding', 'a8b27725fe58719daf61810814e3e98af3e417eb2a1a2956b59e8cccc4c2e633', '79cee8a954732941abd21bc2ee45c8812ca13955cd3e2aeecb20ed0f59b009bf'), (15, 'scoped_recording_inbox', '79e86a3017debee9da43d45a41d313ce8658044a05b40a43f62726f7c8777365', '45f1b72880873099b8e55a2e726971fa8ad31028be83aca1e9c6bddf26624cb4'), (16, 'guest_notification_fence', '085fe788b7cef561bf7504c887347a4705b749b317584ab8ddcea465dd400975', '8f4def170b0e1733ceefc4ddae4ad6d2d73b504cefb2156951cfc88e5b675665')) f(version, name, up, down) USING (version)
      WHERE a.version IS NULL OR f.version IS NULL OR a.name <> f.name OR a.up_checksum <> f.up OR a.down_checksum <> f.down OR a.environment <> 'test'), (SELECT string_agg(version::text, ',' ORDER BY version) FROM booking_migrations.applied)
UNION ALL
SELECT 'new_tables_present', (to_regclass('booking.api_rate_limits') IS NOT NULL AND to_regclass('booking.recording_holds') IS NOT NULL AND to_regclass('booking.recording_assessments') IS NOT NULL
       AND to_regclass('booking.notification_renders') IS NOT NULL AND to_regclass('booking.notification_latches') IS NOT NULL AND to_regclass('booking.notification_write_authority') IS NOT NULL), NULL
UNION ALL
SELECT 'rls_on_every_booking_table', NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'booking'::regnamespace AND c.relkind = 'r' AND NOT c.relrowsecurity), NULL
UNION ALL
SELECT 'no_public_anon_authenticated_table_grants', NOT EXISTS (SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a
       WHERE c.relnamespace = 'booking'::regnamespace AND (a.grantee = 0 OR a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon', 'authenticated')))), NULL
UNION ALL
SELECT 'runtime_privilege_matrix_exact_0016', NOT EXISTS (
       SELECT 1 FROM (VALUES ('instance', 'SELECT'), ('intents', 'INSERT,SELECT,UPDATE'), ('intent_work', 'INSERT,SELECT,UPDATE'), ('payment_attempts', 'INSERT,SELECT,UPDATE'), ('external_operations', 'INSERT,SELECT,UPDATE'), ('hostaway_reservation_attempts', 'INSERT,SELECT,UPDATE'), ('payment_refunds', 'INSERT,SELECT,UPDATE'), ('stripe_webhook_events', 'INSERT,SELECT,UPDATE'), ('inventory_claims', 'INSERT,SELECT'), ('reconciliation_cases', 'INSERT,SELECT'), ('intent_transitions', 'INSERT,SELECT'), ('intent_applied_events', 'INSERT,SELECT'), ('payment_ledger', 'INSERT,SELECT'), ('intent_guests', 'INSERT,SELECT'), ('provider_evidence', 'SELECT'), ('reconciliation_resolutions', 'SELECT'), ('definite_refusal_codes', 'SELECT'), ('api_rate_limits', ''), ('recording_holds', 'SELECT'), ('recording_hold_decisions', 'SELECT'), ('recording_hold_observations', 'SELECT'), ('recording_conflict_inbox', 'SELECT'), ('recording_assessment_codes', 'SELECT'), ('recording_assessments', 'SELECT'), ('recording_claim_assessments', 'SELECT'), ('notification_renders', 'SELECT'), ('notification_latches', 'SELECT'), ('notification_write_authority', '')) e(tbl, privs)
       FULL JOIN (SELECT c.relname AS tbl, coalesce((SELECT string_agg(DISTINCT a.privilege_type, ',' ORDER BY a.privilege_type) FROM aclexplode(c.relacl) a
                    WHERE a.grantee = (SELECT oid FROM pg_roles WHERE rolname = 'mv_booking_app')), '') AS privs
                  FROM pg_class c WHERE c.relnamespace = 'booking'::regnamespace AND c.relkind = 'r') g USING (tbl)
       WHERE e.tbl IS NULL OR g.tbl IS NULL OR e.privs <> g.privs), NULL
UNION ALL
SELECT 'btree_gist', (SELECT count(*) = 1 FROM pg_extension WHERE extname = 'btree_gist'), (SELECT extversion FROM pg_extension WHERE extname = 'btree_gist')
UNION ALL
SELECT 'runtime_functions_executable', (SELECT bool_and(has_function_privilege('mv_booking_app', f, 'EXECUTE')) FROM unnest(ARRAY['booking.claim_release_blockers(uuid)', 'booking.release_claim_if_safe(uuid,text)', 'booking.release_completed_stays()', 'booking.purge_guest_data(integer,integer)', 'booking.settle_operation_from_evidence(uuid,uuid)', 'booking.record_provider_evidence(uuid,text,text,text,jsonb,text)', 'booking.rate_limit_hit(text,integer,integer)']::text[]) f), NULL
UNION ALL
SELECT 'admin_functions_not_executable', (SELECT NOT bool_or(has_function_privilege('mv_booking_app', f, 'EXECUTE')) FROM unnest(ARRAY['booking.admin_resolve_operation(uuid,text,uuid[],text,text,text,timestamptz)', 'booking.admin_resolve_intent(uuid,text,uuid[],text,text,text,timestamptz)', 'booking.admin_close_case(uuid,uuid[],text,text,timestamptz)', 'booking.admin_record_evidence(uuid,text,text,text,jsonb,timestamptz,text,text)', 'booking.admin_acquire_claim(uuid,timestamptz)']::text[]) f), NULL
UNION ALL
SELECT 'roles_groups_nologin', (SELECT count(*) = 3 AND bool_and(NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls) FROM pg_roles WHERE rolname IN ('mv_booking_admin', 'mv_booking_app', 'mv_booking_report')), NULL
UNION ALL
SELECT 'runtime_login_mv_booking_app_dev', (SELECT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb FROM pg_roles WHERE rolname = 'mv_booking_app_dev') IS TRUE,
       (SELECT string_agg(g.rolname, ',' ORDER BY g.rolname) FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid JOIN pg_roles r ON r.oid = m.member WHERE r.rolname = 'mv_booking_app_dev')
UNION ALL
SELECT 'runtime_login_member_of_app_only', (SELECT string_agg(g.rolname, ',' ORDER BY g.rolname) FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid JOIN pg_roles r ON r.oid = m.member WHERE r.rolname = 'mv_booking_app_dev') IS NOT DISTINCT FROM 'mv_booking_app', NULL
UNION ALL
SELECT 'other_logins_in_booking_groups', true, (SELECT string_agg(r.rolname, ',' ORDER BY r.rolname) FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid JOIN pg_roles r ON r.oid = m.member WHERE g.rolname LIKE 'mv\_booking\_%' AND r.rolcanlogin AND r.rolname <> 'mv_booking_app_dev')
UNION ALL
SELECT 'data_counts', true, (SELECT format('intents=%s guests=%s attempts=%s ops=%s notify_ops=%s cases=%s webhook_events=%s claims=%s ledger=%s',
       (SELECT count(*) FROM booking.intents), (SELECT count(*) FROM booking.intent_guests), (SELECT count(*) FROM booking.payment_attempts),
       (SELECT count(*) FROM booking.external_operations), (SELECT count(*) FROM booking.external_operations WHERE op_type = 'guest.notify'),
       (SELECT count(*) FROM booking.reconciliation_cases), (SELECT count(*) FROM booking.stripe_webhook_events), (SELECT count(*) FROM booking.inventory_claims),
       (SELECT count(*) FROM booking.payment_ledger)));
ROLLBACK;
